using System.Security.Cryptography;

namespace Terraria.NxCrypto;

public static class NxCrypto
{
    public static ICryptoTransform CreateEncryptor(byte[] rgbKey, byte[]? rgbIV) => new AesTransform(rgbKey, rgbIV, encrypt: true);
    public static ICryptoTransform CreateDecryptor(byte[] rgbKey, byte[]? rgbIV) => new AesTransform(rgbKey, rgbIV, encrypt: false);

    private sealed class AesTransform : ICryptoTransform
    {
        private readonly byte[] _roundKeys;
        private readonly byte[] _chain = new byte[16];
        private readonly bool _encrypt;
        private readonly List<byte> _pending = new();
        public bool CanReuseTransform => false;
        public bool CanTransformMultipleBlocks => true;
        public int InputBlockSize => 16;
        public int OutputBlockSize => 16;
        public AesTransform(byte[] key, byte[]? iv, bool encrypt)
        {
            if (key == null || key.Length != 16) throw new CryptographicException("NxCrypto supports AES-128 keys only");
            if (iv == null || iv.Length != 16) throw new CryptographicException("NxCrypto requires a 128-bit IV");
            _roundKeys = ExpandKey(key); Buffer.BlockCopy(iv, 0, _chain, 0, 16); _encrypt = encrypt;
        }
        public void Dispose() { Array.Clear(_chain); Array.Clear(_roundKeys); _pending.Clear(); }
        public int TransformBlock(byte[] inputBuffer, int inputOffset, int inputCount, byte[] outputBuffer, int outputOffset)
        {
            if (inputCount % 16 != 0) throw new CryptographicException("inputCount must be a multiple of 16");
            if (!_encrypt)
            {
                int total = _pending.Count + inputCount; if (total <= 16) { for (int i=0;i<inputCount;i++) _pending.Add(inputBuffer[inputOffset+i]); return 0; }
                int emit = total - 16; emit -= emit % 16; var buf = new byte[_pending.Count + inputCount]; _pending.CopyTo(buf); Buffer.BlockCopy(inputBuffer,inputOffset,buf,_pending.Count,inputCount); int written = ProcessFull(buf,0,emit,outputBuffer,outputOffset); _pending.Clear(); for(int i=emit;i<buf.Length;i++) _pending.Add(buf[i]); return written;
            }
            return ProcessFull(inputBuffer,inputOffset,inputCount,outputBuffer,outputOffset);
        }
        public byte[] TransformFinalBlock(byte[] inputBuffer, int inputOffset, int inputCount)
        {
            if (_encrypt)
            {
                int pad = 16 - (inputCount % 16); var buf = new byte[inputCount + pad]; Buffer.BlockCopy(inputBuffer,inputOffset,buf,0,inputCount); for(int i=inputCount;i<buf.Length;i++) buf[i]=(byte)pad; var outb=new byte[buf.Length]; ProcessFull(buf,0,buf.Length,outb,0); return outb;
            }
            var all = new byte[_pending.Count + inputCount]; _pending.CopyTo(all); Buffer.BlockCopy(inputBuffer,inputOffset,all,_pending.Count,inputCount); if (all.Length==0 || all.Length%16!=0) throw new CryptographicException("bad final AES block length"); var res=new byte[all.Length]; ProcessFull(all,0,all.Length,res,0); _pending.Clear(); return res;
        }
        private int ProcessFull(byte[] input, int inputOffset, int count, byte[] output, int outputOffset)
        {
            Span<byte> block = stackalloc byte[16]; Span<byte> tmp = stackalloc byte[16];
            for (int off=0; off<count; off+=16)
            {
                input.AsSpan(inputOffset+off,16).CopyTo(block);
                if (_encrypt) { for(int i=0;i<16;i++) block[i]^=_chain[i]; EncryptBlock(block); block.CopyTo(output.AsSpan(outputOffset+off,16)); block.CopyTo(_chain); }
                else { block.CopyTo(tmp); DecryptBlock(block); for(int i=0;i<16;i++) block[i]^=_chain[i]; block.CopyTo(output.AsSpan(outputOffset+off,16)); tmp.CopyTo(_chain); }
            }
            return count;
        }
        private void EncryptBlock(Span<byte> s){ AddRoundKey(s,0); for(int r=1;r<10;r++){SubBytes(s); ShiftRows(s); MixColumns(s); AddRoundKey(s,r);} SubBytes(s); ShiftRows(s); AddRoundKey(s,10); }
        private void DecryptBlock(Span<byte> s){ AddRoundKey(s,10); for(int r=9;r>0;r--){InvShiftRows(s); InvSubBytes(s); AddRoundKey(s,r); InvMixColumns(s);} InvShiftRows(s); InvSubBytes(s); AddRoundKey(s,0); }
        private void AddRoundKey(Span<byte> s,int r){int o=r*16; for(int i=0;i<16;i++) s[i]^=_roundKeys[o+i];}
        private static void SubBytes(Span<byte>s){for(int i=0;i<16;i++)s[i]=S[s[i]];} private static void InvSubBytes(Span<byte>s){for(int i=0;i<16;i++)s[i]=Si[s[i]];}
        private static void ShiftRows(Span<byte>s){ (s[1],s[5],s[9],s[13])=(s[5],s[9],s[13],s[1]); (s[2],s[6],s[10],s[14])=(s[10],s[14],s[2],s[6]); (s[3],s[7],s[11],s[15])=(s[15],s[3],s[7],s[11]); }
        private static void InvShiftRows(Span<byte>s){ (s[1],s[5],s[9],s[13])=(s[13],s[1],s[5],s[9]); (s[2],s[6],s[10],s[14])=(s[10],s[14],s[2],s[6]); (s[3],s[7],s[11],s[15])=(s[7],s[11],s[15],s[3]); }
        private static byte X(byte a, byte b){byte r=0; while(b>0){if((b&1)!=0)r^=a; bool hi=(a&0x80)!=0; a<<=1; if(hi)a^=0x1b; b>>=1;} return r;}
        private static void MixColumns(Span<byte>s){ for(int c=0;c<4;c++){int i=c*4; byte a=s[i],b=s[i+1],d=s[i+2],e=s[i+3]; s[i]=(byte)(X(a,2)^X(b,3)^d^e); s[i+1]=(byte)(a^X(b,2)^X(d,3)^e); s[i+2]=(byte)(a^b^X(d,2)^X(e,3)); s[i+3]=(byte)(X(a,3)^b^d^X(e,2)); }}
        private static void InvMixColumns(Span<byte>s){ for(int c=0;c<4;c++){int i=c*4; byte a=s[i],b=s[i+1],d=s[i+2],e=s[i+3]; s[i]=(byte)(X(a,14)^X(b,11)^X(d,13)^X(e,9)); s[i+1]=(byte)(X(a,9)^X(b,14)^X(d,11)^X(e,13)); s[i+2]=(byte)(X(a,13)^X(b,9)^X(d,14)^X(e,11)); s[i+3]=(byte)(X(a,11)^X(b,13)^X(d,9)^X(e,14)); }}
        private static byte[] ExpandKey(byte[] key){var w=new byte[176]; Buffer.BlockCopy(key,0,w,0,16); int bytes=16, rcon=1; Span<byte> t=stackalloc byte[4]; while(bytes<176){for(int i=0;i<4;i++)t[i]=w[bytes-4+i]; if(bytes%16==0){(t[0],t[1],t[2],t[3])=(S[t[1]],S[t[2]],S[t[3]],S[t[0]]); t[0]^=(byte)rcon; rcon=X((byte)rcon,2);} for(int i=0;i<4;i++){w[bytes]=(byte)(w[bytes-16]^t[i]); bytes++;}} return w;}
        private static readonly byte[] S = {0x63,0x7c,0x77,0x7b,0xf2,0x6b,0x6f,0xc5,0x30,0x01,0x67,0x2b,0xfe,0xd7,0xab,0x76,0xca,0x82,0xc9,0x7d,0xfa,0x59,0x47,0xf0,0xad,0xd4,0xa2,0xaf,0x9c,0xa4,0x72,0xc0,0xb7,0xfd,0x93,0x26,0x36,0x3f,0xf7,0xcc,0x34,0xa5,0xe5,0xf1,0x71,0xd8,0x31,0x15,0x04,0xc7,0x23,0xc3,0x18,0x96,0x05,0x9a,0x07,0x12,0x80,0xe2,0xeb,0x27,0xb2,0x75,0x09,0x83,0x2c,0x1a,0x1b,0x6e,0x5a,0xa0,0x52,0x3b,0xd6,0xb3,0x29,0xe3,0x2f,0x84,0x53,0xd1,0x00,0xed,0x20,0xfc,0xb1,0x5b,0x6a,0xcb,0xbe,0x39,0x4a,0x4c,0x58,0xcf,0xd0,0xef,0xaa,0xfb,0x43,0x4d,0x33,0x85,0x45,0xf9,0x02,0x7f,0x50,0x3c,0x9f,0xa8,0x51,0xa3,0x40,0x8f,0x92,0x9d,0x38,0xf5,0xbc,0xb6,0xda,0x21,0x10,0xff,0xf3,0xd2,0xcd,0x0c,0x13,0xec,0x5f,0x97,0x44,0x17,0xc4,0xa7,0x7e,0x3d,0x64,0x5d,0x19,0x73,0x60,0x81,0x4f,0xdc,0x22,0x2a,0x90,0x88,0x46,0xee,0xb8,0x14,0xde,0x5e,0x0b,0xdb,0xe0,0x32,0x3a,0x0a,0x49,0x06,0x24,0x5c,0xc2,0xd3,0xac,0x62,0x91,0x95,0xe4,0x79,0xe7,0xc8,0x37,0x6d,0x8d,0xd5,0x4e,0xa9,0x6c,0x56,0xf4,0xea,0x65,0x7a,0xae,0x08,0xba,0x78,0x25,0x2e,0x1c,0xa6,0xb4,0xc6,0xe8,0xdd,0x74,0x1f,0x4b,0xbd,0x8b,0x8a,0x70,0x3e,0xb5,0x66,0x48,0x03,0xf6,0x0e,0x61,0x35,0x57,0xb9,0x86,0xc1,0x1d,0x9e,0xe1,0xf8,0x98,0x11,0x69,0xd9,0x8e,0x94,0x9b,0x1e,0x87,0xe9,0xce,0x55,0x28,0xdf,0x8c,0xa1,0x89,0x0d,0xbf,0xe6,0x42,0x68,0x41,0x99,0x2d,0x0f,0xb0,0x54,0xbb,0x16};
        private static readonly byte[] Si = {0x52,0x09,0x6a,0xd5,0x30,0x36,0xa5,0x38,0xbf,0x40,0xa3,0x9e,0x81,0xf3,0xd7,0xfb,0x7c,0xe3,0x39,0x82,0x9b,0x2f,0xff,0x87,0x34,0x8e,0x43,0x44,0xc4,0xde,0xe9,0xcb,0x54,0x7b,0x94,0x32,0xa6,0xc2,0x23,0x3d,0xee,0x4c,0x95,0x0b,0x42,0xfa,0xc3,0x4e,0x08,0x2e,0xa1,0x66,0x28,0xd9,0x24,0xb2,0x76,0x5b,0xa2,0x49,0x6d,0x8b,0xd1,0x25,0x72,0xf8,0xf6,0x64,0x86,0x68,0x98,0x16,0xd4,0xa4,0x5c,0xcc,0x5d,0x65,0xb6,0x92,0x6c,0x70,0x48,0x50,0xfd,0xed,0xb9,0xda,0x5e,0x15,0x46,0x57,0xa7,0x8d,0x9d,0x84,0x90,0xd8,0xab,0x00,0x8c,0xbc,0xd3,0x0a,0xf7,0xe4,0x58,0x05,0xb8,0xb3,0x45,0x06,0xd0,0x2c,0x1e,0x8f,0xca,0x3f,0x0f,0x02,0xc1,0xaf,0xbd,0x03,0x01,0x13,0x8a,0x6b,0x3a,0x91,0x11,0x41,0x4f,0x67,0xdc,0xea,0x97,0xf2,0xcf,0xce,0xf0,0xb4,0xe6,0x73,0x96,0xac,0x74,0x22,0xe7,0xad,0x35,0x85,0xe2,0xf9,0x37,0xe8,0x1c,0x75,0xdf,0x6e,0x47,0xf1,0x1a,0x71,0x1d,0x29,0xc5,0x89,0x6f,0xb7,0x62,0x0e,0xaa,0x18,0xbe,0x1b,0xfc,0x56,0x3e,0x4b,0xc6,0xd2,0x79,0x20,0x9a,0xdb,0xc0,0xfe,0x78,0xcd,0x5a,0xf4,0x1f,0xdd,0xa8,0x33,0x88,0x07,0xc7,0x31,0xb1,0x12,0x10,0x59,0x27,0x80,0xec,0x5f,0x60,0x51,0x7f,0xa9,0x19,0xb5,0x4a,0x0d,0x2d,0xe5,0x7a,0x9f,0x93,0xc9,0x9c,0xef,0xa0,0xe0,0x3b,0x4d,0xae,0x2a,0xf5,0xb0,0xc8,0xeb,0xbb,0x3c,0x83,0x53,0x99,0x61,0x17,0x2b,0x04,0x7e,0xba,0x77,0xd6,0x26,0xe1,0x69,0x14,0x63,0x55,0x21,0x0c,0x7d};
